15: const MASK = '•'; // U+2022 BULLET — one glyph per hidden character.
16: const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
17: const RUT_SUFFIX = /-[0-9Kk]$/;
18: const DEFAULT_VISIBLE_END = 4;
19: 
20: const dateFormatters = new Map<AppLocale, Intl.DateTimeFormat>();
21: 
22: /** One bullet per hidden char; visible tail verbatim; RUT -K protection (G7–G9). */
23: export function maskDocumentNumber(rawValue: string, visibleEnd: number): string {
24:   const raw = typeof rawValue === 'string' ? rawValue : String(rawValue ?? '');
25:   if (raw.trim().length === 0) {
26:     return '';
27:   }
28: 
29:   const safeVisibleEnd = Number.isFinite(visibleEnd) ? Math.floor(visibleEnd) : DEFAULT_VISIBLE_END;
30:   if (safeVisibleEnd <= 0) {
31:     return MASK.repeat(raw.length);
32:   }
33:   if (raw.length <= safeVisibleEnd) {
34:     return raw;
35:   }
36: 
37:   let visible = safeVisibleEnd;
38:   if (RUT_SUFFIX.test(raw)) {
39:     visible = Math.min(raw.length, Math.max(safeVisibleEnd, 2));
40:   }
41: 
42:   return MASK.repeat(raw.length - visible) + raw.slice(raw.length - visible);
43: }
44: 
45: /** ISO YYYY-MM-DD → local-calendar Intl date; unparseable input is returned unchanged. */
46: export function formatIsoDate(iso: string, locale: AppLocale): string {
47:   const text = typeof iso === 'string' ? iso : String(iso ?? '');
48:   const match = ISO_DATE.exec(text);
49:   if (!match) {
50:     return text;
51:   }
52: 
53:   const year = Number(match[1]);
54:   const month = Number(match[2]);
55:   const day = Number(match[3]);
56:   const date = new Date(year, month - 1, day);
57:   if (
58:     date.getFullYear() !== year ||
59:     date.getMonth() !== month - 1 ||
60:     date.getDate() !== day
61:   ) {
62:     return text;
63:   }
64: 
65:   let formatter = dateFormatters.get(locale);
66:   if (!formatter) {
67:     formatter = new Intl.DateTimeFormat(locale, {
68:       year: 'numeric',
69:       month: 'long',
70:       day: 'numeric',
71:     });
72:     dateFormatters.set(locale, formatter);
73:   }
74:   return formatter.format(date);
75: }
76: 
77: /** COT-<CO|CL>-<YYYYMMDD>-<XXXXXX>; deterministic FNV-1a over a canonical payload (G19). */
78: export function buildQuoteNumber(
79:   country: CountryCode,
80:   payload: Readonly<Record<string, string>>,
81:   clock: Readonly<{ readonly today: Date }>,
82: ): string {
83:   const today = clock.today;
84:   const datePart =
85:     String(today.getFullYear()).padStart(4, '0') +
86:     String(today.getMonth() + 1).padStart(2, '0') +
87:     String(today.getDate()).padStart(2, '0');
88: 
89:   const canonical = [
90:     country,
91:     ...Object.keys(payload)
92:       .sort()
93:       .map((key) => `${key}=${payload[key]}`),
94:   ].join('|');
95: 
96:   let hash = 0x811c9dc5;
97:   for (let index = 0; index < canonical.length; index += 1) {
98:     hash ^= canonical.charCodeAt(index);
99:     hash = Math.imul(hash, 0x01000193);
100:   }
101:   const suffix = (hash >>> 0).toString(36).toUpperCase().padStart(6, '0').slice(-6);
102: 
103:   return `COT-${country}-${datePart}-${suffix}`;
104: }
105: 
106: /** Derived, never persisted; resolves labels/options/booleans/blanks (G1–G6). */
107: export function buildSummarySections(
108:   fields: readonly FormFieldConfig[],
109:   values: Readonly<Record<string, FormValue>>,
110:   documentMaskVisibleEnd: number,
111:   yes: string,
112:   no: string,
113:   blankPlaceholder: string,
114: ): readonly SummarySection[] {
115:   const ordered = [...fields]
116:     .filter((field) => field.section === 'policyholder' || field.section === 'vehicle')
117:     .sort((left, right) => left.order - right.order || left.id - right.id);
118: 
119:   const policyholder: SummaryRow[] = [];
120:   const vehicle: SummaryRow[] = [];
121: 
122:   for (const field of ordered) {
123:     const resolved = resolveRowValue(
124:       field,
125:       values,
126:       documentMaskVisibleEnd,
127:       yes,
128:       no,
129:       blankPlaceholder,
130:     );
131:     if (resolved === null) {
132:       continue;
133:     }
134: 
135:     const row: SummaryRow = { key: field.key, label: field.label, value: resolved };
136:     if (field.section === 'vehicle') {
137:       vehicle.push(row);
138:     } else {
139:       policyholder.push(row);
140:     }
141:   }
142: 
143:   return [
144:     { id: 'policyholder', heading: UI_COPY.summaryTomadorHeading, rows: policyholder },
145:     { id: 'vehicle', heading: UI_COPY.summaryVehicleHeading, rows: vehicle },
146:   ];
147: }
148: 
149: /** Reads the US-02 QuotedPlan verbatim; never recalculates a price. */
150: export function buildPlanSummary(quoted: QuotedPlan, copy: PlanSummaryCopy): PlanSummary {
151:   const { adjustment } = quoted;
152:   const adjustmentText =
153:     adjustment.adjustmentPercent > 0
154:       ? `${copy.adjustmentLabel}: +${adjustment.adjustmentPercent}%` +
155:         (adjustment.reasons.length > 0 ? ` · ${adjustment.reasons.join(', ')}` : '')
156:       : copy.noAdjustment;
157: 
158:   return {
159:     name: quoted.plan.name,
160:     shortDescription: quoted.plan.shortDescription,
161:     basePriceText: `${copy.basePriceLabel}: ${quoted.formattedBasePrice}`,
162:     finalPriceText: `${copy.finalPriceLabel}: ${quoted.formattedFinalPrice}`,
163:     adjustmentText,
164:     footnote: copy.footnote ?? copy.simulatedFootnote ?? '',
165:     finalPrice: quoted.finalPrice,
166:   };
167: }
168: 
169: function resolveRowValue(
170:   field: FormFieldConfig,
171:   values: Readonly<Record<string, FormValue>>,
172:   documentMaskVisibleEnd: number,
173:   yes: string,
174:   no: string,
175:   blankPlaceholder: string,
176: ): string | null {
177:   const raw: FormValue | undefined = values[field.key];
178:   if (isBlank(raw)) {
179:     return field.required ? blankPlaceholder : null;
180:   }
181:   const value = raw as FormValue;
182: 
183:   if (field.key === 'documentNumber') {
184:     return maskDocumentNumber(String(value), documentMaskVisibleEnd);
185:   }
186: 
187:   switch (field.type) {
188:     case 'select': {
189:       const text = String(value);
190:       const option = field.options.find((candidate) => candidate.value === text);
191:       if (option) {
192:         return option.label;
193:       }
194:       warnDev(`[summary] option "${text}" is no longer configured for field "${field.key}".`);
195:       return text;
196:     }
197:     case 'checkbox':
198:       return value === true ? yes : no;
199:     case 'date':
200:       return formatIsoDate(String(value), localeFor(field.country));
201:     case 'number':
202:     case 'text':
203:       return String(value);
204:   }
205: }
206: 
207: function isBlank(value: FormValue | undefined): boolean {
208:   return (
209:     value === null ||
210:     value === undefined ||
211:     (typeof value === 'string' && value.trim().length === 0)
212:   );
213: }
214: 
215: function localeFor(country: CountryCode): AppLocale {
216:   return COUNTRY_CATALOG_BY_CODE[country].locale;
217: }
218: 
219: /** Dev-only warning without importing Angular runtime helpers into the pure helper module. */
220: function warnDev(message: string): void {
221:   const devMode = (globalThis as { ngDevMode?: boolean }).ngDevMode;
222:   if (devMode !== false) {
223:     console.warn(message);
224:   }
225: }

