5: /** Default simulated delay; unit tests can override this token with 0. */
6: export const SIMULATED_PAYMENT_DELAY_MS = new InjectionToken<number>('SIMULATED_PAYMENT_DELAY_MS', {
7:   providedIn: 'root',
8:   factory: () => 600,
9: });
