11: /** Non-UI test hook approved in Checkpoint 3 Q2 Option A. */
12: export const SIMULATED_PAYMENT_FAILURE_HOOK = new InjectionToken<() => boolean>(
13:   'SIMULATED_PAYMENT_FAILURE_HOOK',
14:   {
15:     providedIn: 'root',
16:     factory: () => () => {
17:       const flag = (globalThis as {
18:         __WIZARD_SIMULATE_PAYMENT_FAILURE__?: boolean | (() => boolean);
19:       }).__WIZARD_SIMULATE_PAYMENT_FAILURE__;
20:       return typeof flag === 'function' ? flag() : flag === true;
21:     },
22:   },
23: );
24: 
25: /**
26:  * Frontend-only simulated payment boundary: no HTTP, no storage, no card or
27:  * token data. A rejection is a result value, never an exception.
28:  */
29: @Injectable({ providedIn: 'root' })
30: export class SimulatedPaymentService {
31:   private readonly defaultDelayMs = inject(SIMULATED_PAYMENT_DELAY_MS);
32:   private readonly failureHook = inject(SIMULATED_PAYMENT_FAILURE_HOOK);
33: 
34:   pay(request: SimulatedPaymentRequest): Promise<SimulatedPaymentResult> {
35:     const delayMs = Math.max(0, request.delayMs ?? this.defaultDelayMs);
36:     const shouldFail = request.shouldFail || this.failureHook();
37: 
38:     return new Promise<SimulatedPaymentResult>((resolve) => {
39:       setTimeout(() => {
40:         resolve(
41:           shouldFail
42:             ? { ok: false, code: 'SIMULATED_REJECTION' }
43:             : { ok: true },
44:         );
45:       }, delayMs);
46:     });
47:   }
48: }

