1: import { inject } from '@angular/core';
2: import { CanActivateFn, Router } from '@angular/router';
3: 
4: import { COUNTRY_CATALOG_BY_CODE, toCountryCode } from '../country/country-catalog';
5: import { WizardStore } from '../../features/quote/wizard.store';
6: 
7: /**
8:  * US-02/US-03: Step 3 requires a valid Step 1 and an active selected plan.
9:  * On a cold reload the plan catalogue is not fetched by the Step 1 loader, so a
10:  * persisted selection is resolved here before deciding to bounce back to plans.
11:  */
12: export const step2CompleteGuard: CanActivateFn = async (route) => {
13:   const store = inject(WizardStore);
14:   const router = inject(Router);
15:   const country = toCountryCode(route.paramMap.get('country'));
16:   const segment = COUNTRY_CATALOG_BY_CODE[country].routeSegment;
17: 
18:   if (!store.isLoadedFor(country) || !store.form()?.valid) {
19:     await store.load(country);
20:     if (!store.isLoadedFor(country) || !store.form()?.valid) {
21:       return router.createUrlTree([`/${segment}/quote`]);
22:     }
23:   }
24: 
25:   if (store.selectedPlan() === null) {
26:     const persistedPlanId = store.selectedPlanDocumentId?.() ?? null;
27:     if (persistedPlanId !== null) {
28:       if (store.plansStatus?.() !== 'ready') {
29:         await store.loadPlans(country);
30:       }
31:       if (store.selectedPlan() !== null) {
32:         return true;
33:       }
34:     }
35:     return router.createUrlTree([`/${segment}/quote/plans`]);
36:   }
37: 
38:   return true;
39: };

