213: export function vehicleYearValidator(today: Date = new Date()): ValidatorFn {
214:   return (control: AbstractControl): ValidationErrors | null => {
215:     if (isEmpty(control.value)) {
216:       return null;
217:     }
218:     const numeric = typeof control.value === 'number' ? control.value : Number(control.value);
219:     if (!Number.isFinite(numeric) || !Number.isInteger(numeric)) {
220:       return { vehicleYear: true };
221:     }
222:     const bounds = vehicleYearBounds(today);
223:     return numeric >= bounds.min && numeric <= bounds.max ? null : { vehicleYear: true };
224:   };
