77: /** COT-<CO|CL>-<YYYYMMDD>-<XXXXXX>; deterministic FNV-1a over a canonical payload (G19). */
78: export function buildQuoteNumber(
79:   country: CountryCode,
80:   payload: Readonly<Record<string, string>>,
81:   clock: Readonly<{ readonly today: Date }>,
82: ): string {
83:   const today = clock.today;
84:   const datePart =
85:     String(today.getFullYear()).padStart(4, '0') +
86:     String(today.getMonth() + 1).padStart(2, '0') +
87:     String(today.getDate()).padStart(2, '0');
88: 
89:   const canonical = [
90:     country,
91:     ...Object.keys(payload)
92:       .sort()
93:       .map((key) => `${key}=${payload[key]}`),
94:   ].join('|');
95: 
96:   let hash = 0x811c9dc5;
97:   for (let index = 0; index < canonical.length; index += 1) {
98:     hash ^= canonical.charCodeAt(index);
99:     hash = Math.imul(hash, 0x01000193);
100:   }
101:   const suffix = (hash >>> 0).toString(36).toUpperCase().padStart(6, '0').slice(-6);
102: 
103:   return `COT-${country}-${datePart}-${suffix}`;
104: }
