169: function resolveRowValue(
170:   field: FormFieldConfig,
171:   values: Readonly<Record<string, FormValue>>,
172:   documentMaskVisibleEnd: number,
173:   yes: string,
174:   no: string,
175:   blankPlaceholder: string,
176: ): string | null {
177:   const raw: FormValue | undefined = values[field.key];
178:   if (isBlank(raw)) {
179:     return field.required ? blankPlaceholder : null;
180:   }
181:   const value = raw as FormValue;
182: 
183:   if (field.key === 'documentNumber') {
184:     return maskDocumentNumber(String(value), documentMaskVisibleEnd);
185:   }
186: 
187:   switch (field.type) {
188:     case 'select': {
189:       const text = String(value);
190:       const option = field.options.find((candidate) => candidate.value === text);
191:       if (option) {
192:         return option.label;
193:       }
194:       warnDev(`[summary] option "${text}" is no longer configured for field "${field.key}".`);
195:       return text;
196:     }
197:     case 'checkbox':
198:       return value === true ? yes : no;
199:     case 'date':
200:       return formatIsoDate(String(value), localeFor(field.country));
201:     case 'number':
202:     case 'text':
203:       return String(value);
204:   }
205: }
