  page,
}) => {
  await completeStep1(page, 'CO');

  const chosen = card(page, 'Plan Básico').locator('input[type="radio"]');
  await chosen.check();
  await expect(chosen).toBeChecked();
  await expect(card(page, 'Plan Básico').locator('label')).toContainText('Seleccionado');
